<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class FollowUp extends Model {protected $fillable=['lead_id','assigned_to','due_at','type','notes','status','completed_at'];protected function casts():array{return ['due_at'=>'datetime','completed_at'=>'datetime'];}public function lead(){return $this->belongsTo(Lead::class);}public function assignee(){return $this->belongsTo(User::class,'assigned_to');}}